export type JerseyPattern = "solid" | "stripes" | "band";

// País/moneda vive en su propio archivo liviano (src/data/countries.ts) --
// ver el comentario largo ahi y en CountryContext.tsx: este archivo entero
// se manda al cliente donde sea que se use, asi que un import de
// CountryCode/countries/findCountry desde el layout global (todas las
// paginas, hasta las estaticas) arrastraba el catalogo completo con el.
// Re-exportado aca para no romper al resto del codigo, que sigue
// importando estos nombres desde "@/data/products" como siempre.
export type { CountryCode, Country } from "./countries";
export { countries, findCountry } from "./countries";

// El envío de eBay cargado en el catálogo es, en el 92% de los casos, un
// placeholder en 0 -- el costo real depende del país del comprador y solo
// se sabe pidiéndolo en vivo (ver useLiveOfferTotal). Eso hace que, para
// ORDENAR/FILTRAR por precio en la grilla completa (donde no es viable
// pedir el envío real de cada oferta antes de mostrar algo), una camiseta
// de eBay con envío internacional caro pueda aparecer como "la más
// barata" aunque el total real termine siendo mucho mayor -- se reportó
// justo este caso: $15 + $0 de envío en el catálogo, $33.38 real una vez
// resuelto en vivo. Esta función NO se usa para lo que se le MUESTRA al
// usuario (eso sigue viniendo de bestOfferForCountry/useLiveOfferTotal,
// que sí verifican en vivo) -- solo para que el ORDEN no quede engañado
// por ese placeholder. La estimación (~€13, la media real de los envíos
// de eBay que sí vienen con dato en el feed) es aproximada a propósito:
// mejor una estimación conservadora que confiar en un cero que sabemos
// que casi nunca es real.
const EBAY_ZERO_SHIPPING_SORT_ESTIMATE_EUR = 13;

export function sortSafeOfferTotalInEUR(offer: Offer): number {
  const total = offerTotalInEUR(offer);
  if (offer.store === "eBay" && offer.shipping === 0) {
    return total + EBAY_ZERO_SHIPPING_SORT_ESTIMATE_EUR;
  }
  return total;
}

// A qué países envía cada tienda. "all" = envío global.
// El feed de producto (Awin) no trae este dato (columnas "shipping" y
// "ships_from_country" vacías para las dos tiendas), así que se verificó
// a mano en la política de envío publicada por cada tienda:
// - FansJerseyHub: "FREE Shipping Worldwide" (fansjerseyhub1.com/policies/shipping-policy)
// - PlanetFoot: tiene tarifa específica para "Reste du monde" / resto del
//   mundo, además de sus zonas de Europa (planetfoot.com/policies/shipping-policy)
// Un store que no está en este mapa cae al default "envía a todos lados"
// en offerShipsTo, así que agregarlas acá es solo para dejar documentado
// que es un hecho verificado y no una suposición.




export interface Offer {
  store: string;
  price: number;
  shipping: number;
  currency: "EUR" | "USD" | "GBP" | "BRL" | "CLP" | "ARS";
  url: string;
  inStock: boolean;
  sizes: Size[];
  // Foto real del producto provista por la tienda en su feed de Awin.
  // Ausente para ofertas de ejemplo (placeholder).
  imageUrl?: string;
  // Nombre real del producto tal como aparece en la página de esa tienda
  // (nunca inventado). Ausente = todavía no se cargó.
  title?: string;
}

export interface Product {
  id: string;
  teamKey: TeamKey;
  season: string;
  typeKey: TypeKey;
  colorHex: string;
  colorHexSecondary: string;
  jerseyPattern: JerseyPattern;
  offers: Offer[];
  // Ausente = "men" (así no hay que tocar los productos ya existentes).
  ageGroup?: AgeGroup;
  // Marca real del fabricante, sacada de la propia columna brand/brand_name
  // del feed de cada tienda (o "vendor" en el caso de Mystery Shirt Club).
  // Ausente = no se pudo determinar la marca desde el feed.
  brand?: Brand;
}

// NOTA: datos de ejemplo (placeholder) para poder mostrar la interfaz
// mientras se gestionan las afiliaciones reales (Awin, CJ, Rakuten, etc).
// Una vez aprobadas, este archivo se reemplaza por datos que vienen
// de los feeds de producto de cada red. Los nombres de tienda son
// ficticios a propósito.
// Catálogo con ofertas reales de los programas de afiliados ya aprobados en Awin
// (FansJerseyHub, PlanetFoot) para las camisetas que matchean nuestros equipos
// curados. Donde todavía no hay una tienda aprobada que venda esa camiseta,
// se mantienen datos de ejemplo (placeholder) hasta conseguir esa afiliación.
// Nota: "shipping" real no viene en el feed usado (Google Shopping format),
// se asume 0 hasta tener ese dato. FansJerseyHub reporta "out_of_stock" para
// TODO su catálogo en el feed (bug de su lado) por lo que inStock se fuerza
// a true para esa tienda; PlanetFoot sí usa su disponibilidad real.
